  'b7wqcpujtu': R`$\frac{⟦0⟧}{⟦1⟧}$ を小数で表しなさい。`,
  '1ufy8j9fr2y': R`分子を分母でわります：$⟦0⟧ \div ⟦1⟧ = ⟦2⟧$。`,
  'vje0snups3': R`小数第一位`,
  '1liz42210hc': R`小数第一位`,
