  '10rdjn6n7af': R`⟦0⟧のすぐ下の位の数字を見て、⟦1⟧ を <b>⟦2⟧</b> にします。`,
  'srl9a8gbof': R`<b>いちばん大きい</b>小数はどれですか。&nbsp;⟦0⟧`,
  'gs5zz0z26m': R`<b>いちばん小さい</b>小数はどれですか。&nbsp;⟦0⟧`,
