  // percent
  'r0jl598zxh': R`
<p><b>百分率（パーセント）</b>は「100 あたりいくつか」を表します：$35\% = \frac{35}{100} = 0.35$。</p>
⟦0⟧
<h3>3 つの基本の問題</h3>
⟦1⟧
⟦2⟧
<h3>増加・減少と割引</h3>
<p>80 ドルの品物が $20\%$ 引きなら、$0.2 \times 80 = 16$ ドル安くなるので、売り値は $80 - 16 = 64$ ドルです。もっと速い方法：定価の $80\%$ をはらうと考えて $0.8 \times 80 = 64$。</p>
<p>$p\%$ 増えると $1 + \frac{p}{100}$ 倍、$p\%$ 減ると $1 - \frac{p}{100}$ 倍になります。</p>
⟦3⟧`,
  '2e1ivkcc9wi': R`分数`,
  '21lfn42y4af': R`小数`,
  '1vaz29jk1go': R`百分率`,
  '1lj32zs95qv': R`<ul><li><b>ある量の何 %：</b> $N \text{ の } p\% = \frac{p}{100} \times N$。</li><li><b>$a$ は $b$ の何 % か：</b> $\frac{a}{b} \times 100\%$。</li><li><b>変化の割合：</b> $\frac{\text{変化した量}}{\text{もとの量}} \times 100\%$。</li></ul>`,
  '14zii6dfm6x': R`<p>$240$ の $15\%$ は $0.15 \times 240 = 36$。&nbsp; 暗算のコツ：$10\% = 24$、$5\% = 12$、合わせて $36$。</p>`,
  '1xvrzy7qz2k': R`<p>変化の割合は、いつも<b>もとの</b>量でわります。値段が 50 から 60 に上がったら、$\frac{10}{50} = 20\%$ の増加で、$\frac{10}{60}$ ではありません。</p>`,
  '1gobo82ltgo': R`⟦1⟧ の ⟦0⟧% はいくつですか。`,
  '17t3n1yumuv': R`$⟦1⟧ \text{ の } ⟦0⟧\% = \frac{⟦2⟧}{100} \times ⟦3⟧ = ⟦4⟧$。`,
  'x6d2i6pjon': R`⟦1⟧ は ⟦0⟧ の何 % ですか。`,
  '166o0aldzl7': R`$\frac{⟦0⟧}{⟦1⟧}$ を百分率で表しなさい。`,
  '1zxz5pk8y96': R`⟦0⟧ ドルのジャケットが ⟦1⟧% 引きで売られています。売り値はいくらですか。`,
  '1fg7th2fl2k': R`ドル`,
  '2d5e1injpmi': R`値引き額 $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$。売り値 $= ⟦3⟧ - ⟦4⟧ = ⟦5⟧$ ドル。`,
  '188c7uiuhvg': R`ある町の人口は ⟦0⟧ 人です。人口が ⟦1⟧% 増えると、新しい人口は何人ですか。`,
  '1z4269yh9sc': R`増加分 $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$。新しい人口 $= ⟦3⟧ + ⟦4⟧ = ⟦5⟧$。`,
  '24ppsoc883t': R`本の値段が ⟦0⟧ ドルから ⟦1⟧ ドルに変わりました。何 % 値上がりしましたか。`,
  '18zivp6w2kh': R`本の値段が ⟦0⟧ ドルから ⟦1⟧ ドルに変わりました。何 % 値下がりしましたか。`,
  '275khxq1hou': R`変化した量：⟦0⟧ ドル。増加の割合：⟦1⟧ — いつも<b>もとの</b>値段でわります。`,
  '260avkxsjev': R`変化した量：⟦0⟧ ドル。減少の割合：⟦1⟧ — いつも<b>もとの</b>値段でわります。`,

  // measurement
