  '149iz1sgt': R`1 分 = 60 秒 · 1 時間 = 60 分 · 1 日 = 24 時間 · 1 週間 = 7 日`,
  '2g0x2qx5tup': R`<p><b>大きい</b>単位から<b>小さい</b>単位になおすと数が大きくなるので<b>かけ算</b>、小さい単位から大きい単位なら<b>わり算</b>です。</p>`,
  'x1upmnco35': R`<p>$3.5 \text{ km} = 3.5 \times 1000 = 3{,}500 \text{ m}$。&nbsp; $2{,}750 \text{ g} = 2{,}750 \div 1000 = 2.75 \text{ kg}$。</p>`,
  't9d9f384y5': R`<p>時刻をふつうの数のようにひき算してはいけません。$13{:}10 - 9{:}35$ は $1310 - 935 = 375$ 分ではありません。</p>`,
  'q3mks7cmvp': R`⟦0⟧ ⟦1⟧ を ⟦2⟧ で表しなさい。`,
