  '1640fwpwscw': R`電車が ⟦0⟧ に出発し、同じ日の ⟦1⟧ に着きます。乗っている時間は何分ですか。`,
  '1bvdcgo9oas': R`⟦0⟧ から ⟦1⟧ までは ⟦2⟧ 時間 ⟦3⟧ 分なので、$⟦4⟧ \times 60 + ⟦5⟧ = ⟦6⟧$ 分です。`,
  'jz7sp6v78m': R`⟦0⟧ m ⟦1⟧ cm と ⟦2⟧ m ⟦3⟧ cm をたしなさい。答えは cm で表しなさい。`,
  '1v59jh3egmq': R`⟦0⟧ m ⟦1⟧ cm = ⟦2⟧ cm、⟦3⟧ m ⟦4⟧ cm = ⟦5⟧ cm。合計：$⟦6⟧ + ⟦7⟧ = ⟦8⟧$ cm。`,
