  '1mgnf9acc40': R`三角形の内角の和は $180^\circ$ です：$180^\circ - ⟦0⟧^\circ - ⟦1⟧^\circ = ⟦2⟧^\circ$。`,
  '17ra9ybal44': R`一直線上に 2 つの角が並んでいます。一方が $⟦0⟧^\circ$ のとき、もう一方は何度ですか。`,
  '1uo9pac72dr': R`一直線上の角の和は $180^\circ$ です：$180^\circ - ⟦0⟧^\circ = ⟦1⟧^\circ$。`,
  'lbqlw4yngj': R`1 点のまわりに 4 つの角があります。そのうち 3 つが $⟦0⟧^\circ$、$⟦1⟧^\circ$、$⟦2⟧^\circ$ のとき、残りの角は何度ですか。`,
  '1q0g9lewnyf': R`1 点のまわりの角の和は $360^\circ$ です：$360^\circ - ⟦0⟧^\circ - ⟦1⟧^\circ - ⟦2⟧^\circ = ⟦3⟧^\circ$。`,
  '1o7rxocgbe4': R`$⟦0⟧^\circ$ の角は何という角ですか。`,
  '2087xqcuhit': R`鋭角 $\lt 90^\circ$、直角 $= 90^\circ$、鈍角は $90^\circ$ と $180^\circ$ の間、平角 $= 180^\circ$、優角は $180^\circ$ と $360^\circ$ の間です。したがって $⟦0⟧^\circ$ の角は<b>⟦1⟧</b>です。`,
  '1em7emit9v': R`四角形の 3 つの角が $⟦0⟧^\circ$、$⟦1⟧^\circ$、$⟦2⟧^\circ$ です。残りの角は何度ですか。`,
  '24pznbwnbef': R`四角形の内角の和は $360^\circ$ です：$360^\circ - ⟦0⟧^\circ - ⟦1⟧^\circ - ⟦2⟧^\circ = ⟦3⟧^\circ$。`,
  '2egzcjm3tpx': R`五角形`,
