  'gm8iaj6tll': R`$⟦0⟧ - 2 = ⟦1⟧$ 個の三角形に分けられます：$⟦2⟧ \times 180^\circ = ⟦3⟧^\circ$。`,
  'qinptcb6uu': R`⟦0⟧ 本の辺をもつ正多角形（⟦1⟧）の 1 つの内角は何度ですか。`,
  '1do1n0lapzc': R`内角の和 $= (⟦0⟧ - 2) \times 180^\circ = ⟦1⟧^\circ$ を ⟦2⟧ 個の等しい角で分けます：$⟦3⟧^\circ \div ⟦4⟧ = ⟦5⟧^\circ$。`,
  '2b3ubiiwfr4': R`二等辺三角形で、等しい 2 辺の間の角（頂角）が $⟦0⟧^\circ$ です。残りの 2 つの角はそれぞれ何度ですか。`,
  '1m260esohws': R`2 つの底角は等しいので：$\frac{180^\circ - ⟦0⟧^\circ}{2} = ⟦1⟧^\circ$。`,

