  'y08mdvxdvx': R`<ul><li><b>同符号の和：</b>絶対値の和に共通の符号をつける。$-4 + (-9) = -13$。</li><li><b>異符号の和：</b>絶対値の差に、絶対値の大きいほうの符号をつける。$-11 + 5 = -6$。</li><li><b>減法</b>は、ひく数の符号を変えて加えることと同じ：$3 - (-8) = 3 + 8 = 11$。</li></ul>`,
