  '26rnszv74s7': R`午前 6 時の気温は $⟦0⟧^\circ\text{C}$ でした。正午までに $⟦1⟧^\circ\text{C}$ 上がり、真夜中には正午より $⟦2⟧^\circ\text{C}$ 下がりました。真夜中の気温は何度ですか。`,
  'fyyovqsih2': R`$⟦0⟧ + ⟦1⟧ - ⟦2⟧ = ⟦3⟧$ なので、$⟦4⟧^\circ\text{C}$ です。`,
