  '2b2ar8gx2t7': R`<p>根号の中を簡単にするには、いちばん大きな平方数の因数を根号の外に出します：$\sqrt{ab} = \sqrt{a}\,\sqrt{b}$。</p>$$\sqrt{72} = \sqrt{36 \times 2} = 6\sqrt{2}$$`,
  '28pcl4skbrd': R`<p>$x^3 \cdot x^4$ は $x^7$ で、$x^{12}$ ではありません。同じ底の累乗の積では、指数を<i>たします</i>。また $\sqrt{9 + 16} = 5$ で、$3 + 4$ ではありません。</p>`,
