  // social-arith
  '28qmmxd3nnk': R`
<p>日常のお金の問題は、実は割合（百分率）の問題です。</p>
⟦0⟧
⟦1⟧
⟦2⟧
<h3>値引きと税</h3>
<p>割合は順番に適用します：150 ドルを 20% 引きにしてから 10% の税を加えると、$150 \times 0.8 \times 1.1 = 132$ ドルです。</p>
<h3>単利</h3>
⟦3⟧
<p>1,500 ドルを年利 6% で 3 年間預けると、利息は $1{,}500 \times 0.06 \times 3 = 270$ ドル、合計は 1,770 ドルになります。期間が月単位なら $t = \frac{\text{月数}}{12}$ とします。</p>
<h3>総重量・風袋・正味</h3>
<p><b>総重量</b> = 全体の重さ、<b>風袋</b> = 容器・包装の重さ、<b>正味</b> = 総重量 − 風袋。50 kg の袋で風袋が 2% なら、正味は $50 \times 0.98 = 49$ kg です。</p>
⟦4⟧`,
  '104nn3vx4at': R`用語`,
  '1mb9fntmked': R`原価`,
  '12bh5c74j0l': R`売り手が支払った金額`,
  'p4v89gjsks': R`売値`,
  'ixzwuufb5k': R`買い手が支払う金額`,
  '2dj314tvgil': R`利益`,
  '1b41ckd5mix': R`売値 − 原価（売値 > 原価のとき）`,
  '8exalr20f0': R`損失`,
  '2acjs1v6cv9': R`原価 − 売値（売値 < 原価のとき）`,
  '8cl7h0h70q': R`$$\text{利益率} = \frac{\text{利益}}{\text{原価}} \times 100\% \qquad\qquad \text{売値} = \text{原価} \times \left(1 + \frac{p}{100}\right)$$`,
  '2251p3nt91s': R`<p>400 ドルで仕入れた電話を 460 ドルで売ります。利益 $= 60$ なので、利益率 $= \frac{60}{400} \times 100\% = 15\%$。</p>`,
  '16966flk4n0': R`I = P \times r \times t \qquad \text{(元金} \times \text{年利率} \times \text{年数)}`,
  '8dx80n4t33': R`<p>利益率は常に<b>原価</b>をもとにして計算します。売値ではありません。</p>`,
  'zmoygr0th3': R`ある商人が自転車を ⟦0⟧ ドルで仕入れ、⟦1⟧ ドルで売りました。利益率は何 % ですか。`,
  'hr5vewyo1d': R`ある商人が自転車を ⟦0⟧ ドルで仕入れ、⟦1⟧ ドルで売りました。損失率は何 % ですか。`,
  'w2dibc5j0k': R`⟦0⟧ $= ⟦1⟧$。割合 $= \frac{⟦2⟧}{⟦3⟧} \times 100\% = ⟦4⟧\%$。`,
  '1mg15vgrrsq': R`ある店が電気スタンドを ⟦0⟧ ドルで仕入れ、⟦1⟧% の利益を得たいと考えています。売値をいくらにすればよいですか。`,
  '1znpgx1zz3k': R`$\text{売値} = ⟦0⟧ \times ⟦1⟧ = ⟦2⟧$ ドル。`,
  '1qynlkevtzf': R`1 年間`,
  '265o2h9psz8': R`⟦0⟧ 年間`,
  'z7uavwhcj6': R`⟦0⟧ ドルを年利 ⟦1⟧% の単利で ⟦2⟧預けます。最後の元利合計はいくらですか。`,
  '158pfsp5k1j': R`⟦0⟧ ドルを年利 ⟦1⟧% の単利で ⟦2⟧預けます。利息はいくらですか。`,
  '35ywrebltu': R`$I = P r t = ⟦0⟧ \times ⟦1⟧ \times ⟦2⟧ = ⟦3⟧$ ドル。⟦4⟧`,
  '26yfs6y8h5o': R` 元利合計 $= ⟦0⟧ + ⟦1⟧ = ⟦2⟧$ ドル。`,
  '11eyk8p87p8': R`靴 1 足の値段は ⟦0⟧ ドルです。⟦1⟧% 引きにしたあと、値引き後の価格に ⟦2⟧% の売上税が加わります。最終的な価格はいくらですか。`,
  '1ebjr2t3r5v': R`$⟦0⟧ \times ⟦1⟧ = ⟦2⟧$、さらに $\times ⟦3⟧ = ⟦4⟧$ ドル。`,
  'j3cdki7hbr': R`米の袋の総重量は ⟦0⟧ kg です。風袋は総重量の ⟦1⟧% です。正味の重さを求めなさい。`,
  '91s53sp2z': R`風袋 $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$ kg。正味 $= ⟦3⟧ - ⟦4⟧ = ⟦5⟧$ kg。`,
  '1kvwyquko78': R`腕時計を ⟦0⟧ ドルで売ったところ、利益率は ⟦1⟧% でした。原価はいくらでしたか。`,
  'g36e4lpvm4': R`$\text{売値} = \text{原価} \times ⟦0⟧$ なので、$\text{原価} = \frac{⟦1⟧}{⟦2⟧} = ⟦3⟧$ ドル。（売値から ⟦4⟧% を引くのは誤りです。）`,

  // patterns
  '2bajjwmyt59': R`
<p><b>数列</b>は、数を順に並べたもので、それぞれの数を<b>項</b>といいます。規則を見つければ、続きを書いたり、どの項でも直接求めたりできます。</p>
<h3>等差数列</h3>
<p>毎回同じ数 $d$（<b>公差</b>）をたします：5, 8, 11, 14, … は $d = 3$。</p>
⟦0⟧
<h3>等比数列</h3>
<p>各項に同じ数 $r$（<b>公比</b>）をかけます：3, 6, 12, 24, …（$r = 2$）、80, 40, 20, …（$r = \frac{1}{2}$）。</p>
<h3>特別な数列</h3>
⟦1⟧
⟦2⟧
⟦3⟧`,
  '11v4eu8405a': R`$$u_n = a + (n - 1)d$$<p>ここで $a$ は初項です。5, 8, 11, … では $u_n = 5 + 3(n - 1) = 3n + 2$ なので、$u_{50} = 152$。</p>`,
