  'k4xtnyrrtm': R`<p>7, 11, 15, … の第何項が 95 ですか。$u_n = 4n + 3 = 95$ より $n = 23$：第 23 項です。</p>`,
  'sceh7pz7y9': R`<p>一般項の式の $n$ の係数は公差です。初項ではありません。</p>`,
