  '273m8h7rqm0': R`公差は ⟦0⟧ なので、次の項は $⟦1⟧ ⟦2⟧ = ⟦3⟧$。`,
  'e7rskm3cuq': R`数列 ⟦1⟧, … の第 ⟦0⟧ 項 $u_{⟦0⟧}$ を求めなさい。`,
  '1zj05x9ucbg': R`⟦0⟧, … の一般項を表す式はどれですか。`,
  '10p4kmsov0h': R`項は ⟦0⟧ ずつ増えるので、式は $⟦1⟧n$ から始まります。$n = 1$ のとき $⟦2⟧(1) + c = ⟦3⟧$ より $c = ⟦4⟧$：$u_n = ⟦5⟧$。`,
  'kmsujsbacm': R`各項に ⟦0⟧ をかけているので、次の項は $⟦1⟧ \times ⟦2⟧ = ⟦3⟧$。`,
  '1tqcntwvtfu': R`数列 ⟦0⟧, … の第何項が ⟦1⟧ ですか。`,
  '1i1kg83c5xj': R`$u_n = ⟦0⟧ + (n - 1) \times ⟦1⟧ = ⟦2⟧$ より $(n - 1) \times ⟦3⟧ = ⟦4⟧$、$n - 1 = ⟦5⟧$、$n = ⟦6⟧$。`,
  '1ru4k9e3ubn': R`三角数は 1, 3, 6, 10, 15, … です。三角数 $T_{⟦0⟧}$ を求めなさい。`,
  '1kom1e2tuqt': R`数列 1, 4, 9, 16, 25, … が続きます。第 ⟦0⟧ 項 $u_{⟦0⟧}$ を求めなさい。`,
  '29es9j5bth6': R`これは平方数で $u_n = n^2$ なので、$u_{⟦0⟧} = ⟦1⟧$。`,
  '1jl1l3ooto1': R`ある数列では、第 3 項以降の各項は直前の 2 項の和です。最初の 2 項は ⟦0⟧ と ⟦1⟧ です。第 7 項を求めなさい。`,
