<p><b>変換</b>は図形を動かしたり大きさを変えたりします。平行移動・対称移動・回転移動では像は<b>合同</b>（形も大きさも同じ）、拡大・縮小では<b>相似</b>（形は同じで大きさが違う）になります。</p>
