  '1kfzbnkpyo2': R`O を中心に $k$ 倍に拡大・縮小`,
  '1u5zflf6nl6': R`<p>相似な図形では、対応する角は等しく、対応する辺の比はすべて等しくなります。この比を<b>相似比</b> $k$ といいます。面積は $k^2$ 倍、体積は $k^3$ 倍になります。</p>`,
  'f54rct691f': R`<p>三角形 $ABC$ と $PQR$ は相似で、$AB = 6$、$BC = 8$、$PQ = 9$ です。相似比 $k = \frac{9}{6} = 1.5$ なので $QR = 8 \times 1.5 = 12$。三角形 $ABC$ の面積が 24 なら、三角形 $PQR$ の面積は $24 \times 1.5^2 = 54$ です。</p>`,
  '111he4idz8g': R`<p>長さ 1.5 m の棒の影が 2 m のとき、同時刻に木の影は 12 m でした。三角形は相似なので $\frac{h}{12} = \frac{1.5}{2}$、よって $h = 9$ m。</p>`,
  '1ag7324gyvl': R`<p>相似な図形の辺は、一定の数だけ増えるのではなく、一定の<b>倍率</b>で変わります。ある辺が 6 から 9 になるなら、8 の辺は 11 ではなく 12 になります。</p>`,
  'grtkq2tz50': R`$x$ 軸についての対称移動`,
  '2b146agxtl5': R`$y$ 軸についての対称移動`,
  '12ufv3upbre': R`直線 $y = x$ についての対称移動`,
