  '2ettdugdvou': R`原点を中心とする $180^\circ$ 回転`,
  'y4ewc1f7tf': R`原点を中心とする時計回りの $90^\circ$ 回転`,
  '147bj1yruac': R`$⟦0⟧$ の平行移動`,
  'q8g4eu6egm': R`点 $P⟦0⟧$ を⟦1⟧で移します。像の座標を求めなさい。`,
  'px6a8rprin': R`座標を x, y の形で答えなさい。`,
  '199eqilp9e9': R`移り方は ⟦0⟧ なので、像は $⟦1⟧$。`,
  '141nr4eramb': R`三角形 $ABC$ と $PQR$ は相似で、$AB \leftrightarrow PQ$、$BC \leftrightarrow QR$、$CA \leftrightarrow RP$ が対応しています。$AB = ⟦0⟧$、$BC = ⟦1⟧$、$CA = ⟦2⟧$、$⟦3⟧ = ⟦4⟧$ のとき、$⟦5⟧$ を求めなさい。`,
  '1kimjtrunz7': R`相似比 $k = \frac{⟦0⟧}{⟦1⟧} = ⟦2⟧$。よって $⟦3⟧ = ⟦4⟧ \times ⟦5⟧ = ⟦6⟧$。`,
  'bj1shpkj9u': R`相似な 2 つの立体の相似比は ⟦0⟧ です。小さいほうの体積は ⟦1⟧ cm³ です。大きいほうの体積を求めなさい。`,
  'ld6jtpizu2': R`体積は $k^3 = ⟦0⟧$ 倍：$⟦1⟧ \times ⟦2⟧ = ⟦3⟧$ cm³。`,
  '11duhh78e55': R`相似な 2 つの図形の相似比は ⟦0⟧ です。小さいほうの面積は ⟦1⟧ cm² です。大きいほうの面積を求めなさい。`,
  'hfezjn5dnm': R`面積は $k^2 = ⟦0⟧$ 倍：$⟦1⟧ \times ⟦2⟧ = ⟦3⟧$ cm²。`,
  '2eojcpktunl': R`長さ ⟦0⟧ m の棒の影の長さは ⟦1⟧ m です。同時刻に、木の影の長さは ⟦2⟧ m でした。木の高さを求めなさい。`,
  '196fpe0msid': R`三角形は相似なので $\frac{h}{⟦0⟧} = \frac{⟦1⟧}{⟦2⟧}$、よって $h = ⟦3⟧ \times \frac{⟦4⟧}{⟦5⟧} = ⟦6⟧$ m。`,
  '1iy8baeb4jd': R`点 $⟦0⟧$ を、原点を中心に ⟦1⟧ 倍に拡大（縮小）します。像はどこですか。`,
  '1fyw56nqicr': R`両方の座標に ⟦0⟧ をかけます：$(⟦1⟧ \times ⟦2⟧,\; ⟦3⟧ \times ⟦4⟧) = ⟦5⟧$。`,
