  '12lqix1f1k9': R`⟦0⟧ならば、⟦1⟧。`,
  'z7jgfl3knp': R`逆`,
  'aqxfua2az0': R`裏`,
  '1qj3c13iq5c': R`対偶`,
  '14dtm0889wo': R`命題「⟦1⟧」の<b>⟦0⟧</b>は何ですか？`,
  '1izj6udg2zz': R`逆：仮定と結論を入れかえる（$q \Rightarrow p$）。裏：両方を否定する（$\neg p \Rightarrow \neg q$）。対偶：入れかえて否定する（$\neg q \Rightarrow \neg p$）。よって⟦0⟧は「⟦1⟧」⟦2⟧`,
  '15513xdtwsn': R`——これはもとの命題と同値である。`,
  '6brkkcy85o': R`すべての生徒が試験に合格した。`,
  '2rjnejqvqb': R`試験に合格しなかった生徒がいる。`,
