  't7ja96nwk4': R`ゴールを決めた選手がいる。`,
  '8j4qjj5ufj': R`すべての選手がゴールを決めたわけではない。`,
  'b5r03m1c02': R`「⟦0⟧」の否定は何ですか？`,
  '1a591wdfgbv': R`$\neg(\forall x\, P(x)) \equiv \exists x\, \neg P(x)$：<i>一部</i>が成り立たなければ十分。否定：「⟦0⟧」`,
  'do28na3fol': R`$\neg(\exists x\, P(x)) \equiv \forall x\, \neg P(x)$：1 つも成り立たない。否定：「⟦0⟧」`,
  'ndnufyumww': R`異なる命題変数が ⟦0⟧ 個ある真理値表は何行ありますか？`,
  'u75a1of7f2': R`各変数は 真 か 偽 なので、組合せは $2^{⟦0⟧} = ⟦1⟧$ 通り。`,
  '1w39q86nfhw': R`$⟦0⟧$ の真理値表で、命題が真になる行はいくつありますか？`,
  'ny2shau597': R`表は ⟦0⟧ 行。各行を計算すると、命題が真になるのは <b>⟦1⟧</b> 行、偽になるのは ⟦2⟧ 行。`,
  '1zkv6notm6x': R`試合が中止になる`,
  '28hyo4t2whc': R`試合が中止にならない`,
