  '1zfcrbg8kca': R`植物が育つ`,
  'ax498dx365': R`植物が育たない`,
  '10pj6yxl1t7': R`目覚ましが鳴る`,
  '4ju91rp1va': R`目覚ましが鳴らない`,
  'smmfh9u0rs': R`健太が目を覚ます`,
  '1al6yo6prnr': R`健太が目を覚まさない`,
  '1wbxqjf54ui': R`正しい結論は何も導けない。`,
  '1h3hboouplr': R`前提 1：「⟦0⟧ならば、⟦1⟧。」前提 2：「⟦2⟧。」正しく導ける結論はどれですか？`,
  '19xzw2kl48j': R`これはモーダス・ポネンス（$p \Rightarrow q$、$p$ ⊢ $q$）：「⟦0⟧。」`,
  '4fjcpvhawf': R`これはモーダス・トレンス（$p \Rightarrow q$、$\neg q$ ⊢ $\neg p$）：「⟦0⟧。」`,
