  'd2ku2hqqe6': R`$\frac{1}{n(n+1)} = \frac{1}{n} - \frac{1}{n+1}$ なので、和は打ち消し合って $1 - \frac{1}{⟦0⟧} = \frac{⟦1⟧}{⟦2⟧}$。`,
