  '280l4hqbl71': R`$f(x, y) = ⟦0⟧$ の点 $⟦1⟧$ における $⟦2⟧$ 方向の方向微分係数を求めなさい。`,
  '23ij1mnh3qx': R`$\nabla f = (⟦0⟧, ⟦1⟧)$、単位ベクトルは $\frac{1}{⟦2⟧}⟦3⟧$。$D_{\mathbf{u}}f = \frac{⟦4⟧(⟦5⟧) + ⟦6⟧(⟦7⟧)}{⟦8⟧} = ⟦9⟧$。`,
